import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Ceph QoS: How to support QoS in distributed storage system - Taewoong Kim","description":"","frontmatter":{"title":"Ceph QoS: How to support QoS in distributed storage system - Taewoong Kim","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-23T00:00:00.000Z","tags":["Ceph","QoS","资源分配","调度算法","虚拟化"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_QoS_-_How_to_support_QoS_in_distributed_storage_system_-_Taewoong_Kim.md","filePath":"posts/2018/Ceph_QoS_-_How_to_support_QoS_in_distributed_storage_system_-_Taewoong_Kim.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Ceph_QoS_-_How_to_support_QoS_in_distributed_storage_system_-_Taewoong_Kim.md"};function l(n,o,p,_,g,a){return e(),s("div",null,[...o[0]||(o[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>会议地点</strong>： （未提及）</p><p><strong>参会人员</strong>： Tim King（SK Telecom），其他与会人员</p><p><strong>会议主题</strong>： SK Telecom在Ceph存储系统上的研发工作及未来计划</p><p><strong>会议内容</strong>：</p><p><strong>一、介绍与背景</strong></p><ul><li>Tim King代表SK Telecom介绍其公司在Ceph存储系统上的研发成果和相关工作。</li><li>SK Telecom作为韩国领先的电信公司，旗下拥有SK Broadband和SK Hynix等子公司，分别提供互联网服务和存储解决方案。</li><li>SK Telecom希望通过与OpenStack Ceph社区的协作，实现ICT公司之间的协同效应，并利用其子公司SK Hynix提供的SSD来优化Ceph存储环境。</li></ul><p><strong>二、Ceph存储系统优化</strong></p><ul><li>针对Ceph存储系统在虚拟化环境下的资源竞争和性能问题，SK Telecom提出了以下优化方案： <ul><li><strong>资源分配方法</strong>： 引入优先级队列和最小-最大权重算法，以满足不同用户的需求。</li><li><strong>服务质量保证</strong>： 通过预留、限制控制和比例共享QoS控制，确保关键业务的服务质量。</li></ul></li></ul><p><strong>三、Ceph功能增强</strong></p><ul><li>SK Telecom计划在Ceph中引入以下功能增强： <ul><li><strong>用户空间（US）功能</strong>： 实现更细粒度的资源分配和调度。</li><li><strong>去重功能</strong>： 提高存储空间的利用率。</li><li><strong>私有云和虚拟桌面</strong>： 利用Ceph构建私有云和虚拟桌面，为企业用户提供便捷的存储服务。</li></ul></li></ul><p><strong>四、未来计划</strong></p><ul><li>SK Telecom将继续参与Ceph社区的开发工作，并计划在以下方面进行拓展： <ul><li><strong>支持更多存储系统</strong>： 扩展Ceph的功能，支持更多存储系统。</li><li><strong>社区合作</strong>： 与Ceph社区紧密合作，共同推动Ceph的发展。</li></ul></li></ul><p><strong>五、讨论与总结</strong></p><ul><li>与会人员就Ceph存储系统的优化和功能增强进行了讨论，并提出了以下建议： <ul><li><strong>DM Clock</strong>： 将DM Clock应用于其他SEFs项目，如文件系统中的元数据服务器。</li><li><strong>US功能</strong>： 进一步完善US功能，支持更多存储系统。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>SK Telecom将继续参与Ceph社区的开发工作，并推动Ceph存储系统的优化和功能增强。</li><li>与Ceph社区保持紧密合作，共同推动Ceph的发展。</li></ul>',18)])])}const d=t(r,[["render",l]]);export{S as __pageData,d as default};
